MOD = 10**9 + 7

def count_distinct_substrings(s):
    n = len(s)
    distinct_count = [0] * (n + 1)
    last_occurrence = {}

    for i in range(n):
        if s[i] in last_occurrence:
            distinct_count[i + 1] = distinct_count[i] - distinct_count[last_occurrence[s[i]]]
        else:
            distinct_count[i + 1] = distinct_count[i] + 1
        last_occurrence[s[i]] = i

    return distinct_count

def compute_F(s):
    n = len(s)
    distinct_count = count_distinct_substrings(s)
    total_sum = 0

    for i in range(1, n + 1):
        total_sum += pow(i, distinct_count[i], MOD)
        total_sum %= MOD

    return total_sum

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    index = 1
    results = []

    for _ in range(T):
        S = data[index]
        index += 1
        result = compute_F(S)
        results.append(result)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
